insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (22,'837f7671-f72d-4150-87d6-d33020861082','Roulés au chorizo','Entrée','Facile',15,15,4,'La fameuse recette de ma spécialité : les roulés au chorizo. Si bons, et pourtant si faciles à faire.','🍽️',null,ARRAY['Salé','Rapide','Apéritif','Invités','Fête','Four']::text[],'["150 g de gruyère râpé", "150 g de chorizo", "2 œufs", "1 pâte feuilletée"]'::jsonb,'["Couper le chorizo en morceaux, puis le mixer avec le gruyère râpé.", "Ajouter 1 œuf entier, puis mixer à nouveau jusqu’à obtenir une préparation homogène.", "Dérouler la pâte feuilletée, étaler la préparation au chorizo dessus, puis rouler la pâte bien serrée pour former un boudin.", "Placer le rouleau au réfrigérateur pendant au moins 1 heure pour faciliter la découpe.", "Préchauffer le four à 180°C.", "Couper le rouleau en tranches puis les déposer sur une plaque recouverte de papier cuisson. Vous pouvez les badigeonner avec le jaune du deuxième œuf, puis enfourner environ 15 minutes jusqu’à ce qu’ils soient bien dorés."]'::jsonb,'{}'::bigint[],'2026-07-18T09:50:10.191897+00:00');
insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (13,'837f7671-f72d-4150-87d6-d33020861082','Lentilles saucisses','Plat','Facile',15,40,2,'Une recette si simple que vous ne regarderez plus jamais une boîte de lentilles pareil. Un incontournable français.','🍽️','https://joebqcuqqakymtlbvley.supabase.co/storage/v1/object/public/recipe-images/public/68844c02-4411-47ef-882a-67f39222640a.jpg',ARRAY['Salé','Rapide','Quotidien','Repas de famille','Dîner','Poêle']::text[],'["4 saucisses de Toulouse", "1 oignon", "1 grosse carotte ou 2 petites", "250 g de lentilles", "1 cube de bouillon volaille", "100 g de lardon (facultatif)", "1,5 litre d''eau"]'::jsonb,'["Dans une marmite, faire cuire les saucisses puis les mettre de côté", "Couper l’oignon et les carottes puis les faire légèrement revenir dans la marmite. Y rajouter les lardons.", "Ajouter les lentilles mélanger pendant 2 minutes.", "Ensuite, ajouter le bouillon et recouvrir le tout d’eau. Vous pouvez rajouter un bouquet garni (laurier/ thym)", "Cuire pendant environ 35min avec un couvercle.", "Ajouter les saucisses dans la marmite 5min avant la fin de la cuisson."]'::jsonb,'{}'::bigint[],'2026-05-04T21:05:07.894282+00:00');
insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (23,'837f7671-f72d-4150-87d6-d33020861082','Cake salé protéiné','Entrée','Facile',15,45,4,'Un cake salé simple, gourmand et rassasiant, parfait à préparer à l’avance pour le petit-déj, un apéro, un repas rapide ou à emporter.','🍞',null,ARRAY['Salé','Healthy','Apéritif','Brunch','Invités','Four']::text[],'["6 œufs", "2 petits-suisses 0% MG", "40 g d’huile d’olive", "160 g de farine", "1 sachet de levure chimique", "30 ml de lait demi-écrémé", "200 g d’allumettes de bacon", "1/2 pot d’olives vertes dénoyautées", "2 poignées d’emmental râpé", "2/3 d’un bocal de tomates séchées", "Sel", "Poivre"]'::jsonb,'["Mélanger les œufs avec les petits-suisses.", "Ajouter l’huile d’olive, le sel, le poivre, la farine et la levure chimique, puis mélanger.", "Une fois la pâte homogène, ajouter le lait, les tomates séchées coupées en morceaux, les olives, les allumettes de bacon et l’emmental râpé. Mélanger le tout.", "Verser la préparation dans un moule à cake recouvert de papier cuisson.", "Enfourner pendant 45 minutes à 180°C."]'::jsonb,'{}'::bigint[],'2026-07-18T10:10:19.977889+00:00');
insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (12,'837f7671-f72d-4150-87d6-d33020861082','Quiche truite courgette','Plat','Facile',20,35,4,'La fameuse quiche du CAPES !! Une légende raconte qu''en manger la veille d''un examen nous assures la réussite. Etude réalisé sur un échantillon de deux personnes.','🥧',null,ARRAY['Salé','Healthy','Rapide','Dîner','Déjeuner','Quotidien','Été','Four']::text[],'["2 courgettes", "150 g truite fumée", "25 cl crème fraiche", "2 œufs", "fromage râpé", "1 pate brisée"]'::jsonb,'["Couper les courgettes en tranches fines et les faires cuire une dizaine de minutes dans un poêle avec un filet d''huile d''olive. Salez.", "Dans un récipient mélanger les œufs, la crème.", "Dans un plat à tarte mettre la truite fumée coupée en morceaux, ajouter les courgettes cuites et verser la préparation. Terminer par un peu de fromage rapée.", "Enfourner pendant 35/40 minutes. Le four à 180°C."]'::jsonb,'{}'::bigint[],'2026-05-03T11:27:49.652663+00:00');
insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (17,'837f7671-f72d-4150-87d6-d33020861082','Patates douces façon chili','Plat','Facile',25,35,4,'Grande passion développée pour la patate douce ! Ici, je vous propose une version tex-mex inspirée du chili, mais sans piment dans ma recette : je n’aime vraiment pas ça. Libre à vous d’en ajouter selon vos goûts !','🍽️',null,ARRAY['Salé','Familial','Dîner','Quotidien','Repas de famille','Four','Poêle']::text[],'["4 patates douces", "1 conserve de haricot rouge", "1 petite conserve de maïs", "paprika", "400 g de viande haché", "sel, poivre", "mozzarella râpée"]'::jsonb,'["Couper les patates douces en deux.", "Quadriller légèrement la chair.", "Arroser d''un filet d''huile d''olive et d''une pointe de sel.", "Enfourner 30 minutes à 200 degrés. Surveiller la cuisson elle va varier selon la taille des patates.", "Faire cuire la viande hachée dans une grande poêle.", "Laver les haricots rouges et le maïs.", "Les faires revenir avec la viande haché 5 minutes. Ajouter le paprika et assaisonner.", "Une fois les patates douces bien cuite. Retirer la chaire. Garder la peau de coté.", "Mélanger la chair des patates avec la préparation (viande / haricot / maïs).", "Remplisser les peaux de patates douces avec la préparation.", "Ajouter de la mozzarella râpée, et enfourner 5 minutes pour gratiner à 200 degrés."]'::jsonb,'{}'::bigint[],'2026-05-10T10:28:07.050123+00:00');
insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (18,'837f7671-f72d-4150-87d6-d33020861082','Gâteau aux poires','Sucré','Facile',30,50,4,'Mon incontournable gâteau aux poires : croustillant à l’extérieur et moelleux à l’intérieur. Un véritable délice dont on ne peut plus se passer une fois qu’on l’a goûté ! En revanche, ce n’est pas la recette la plus healthy… mais elle vaut largement l’exception.','🍰🍐',null,ARRAY['Sucré','Goûter','Week-end','Four']::text[],'["150g farine", "100 g sucre", "3 œufs", "10 cl lait", "3 cuillères à soupe d''huile", "2 cuillères à café de levure", "sel", "80 de beurre"]'::jsonb,'["Faite chauffez votre four à 180°", "Dans un saladier, mettez le sucre, deux œufs et une pincée de sel. Fouettez le mélange jusqu''à ce que la préparation mousse et fasse un ruban.", "Incorporez la farine et la levure puis délayer la pâte avec le lait et l''huile.", "Verser la moitié de la pate dans un moule, préalablement beurré et fariné.", "Pelez et épinez les poires, puis couper les en lamelles. Disposer ces lamelles sur la pate au fur et à mesure, puis versez la seconde moitié de la pate par dessus.", "Enfourner et faite cuire 30 minutes.", "Préparer le mélange pour la finition. Faite fondre le beurre à feux doux. Dans le saladier, fouetter l''œuf avec le sucre et lorsque le mélange est homogène ajouter le beurre fondu.", "Au bout des 30 minutes de cuisson, sortez le gâteau du four et versez la préparation à la surface.", "Replacer le gâteau dans le four pendant 20 minutes."]'::jsonb,'{}'::bigint[],'2026-05-26T14:56:40.314875+00:00');
insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (19,'837f7671-f72d-4150-87d6-d33020861082','salade de pate croustillante','Plat','Facile',15,20,1,'Avec l’été vient le retour des salades, et celle-ci est un vrai coup de cœur. Des pâtes croustillantes, du thon, des tomates cerises, une sauce légère au fromage blanc et à la moutarde… tout ce qu’il faut pour rendre la salade de pâtes beaucoup plus fun.','🍽️',null,ARRAY['Salé','Healthy','Rapide','Déjeuner','Quotidien','Four','Poêle']::text[],'["200g de pate crues", "150g de tomate", "50gr d’oignon rouge", "1 sucrine ou salade de votre choix", "180gr de thon au naturel", "100gr de Skyr ou fromage blanc", "1 càc de moutarde à l’ancienne", "1 càc de moutarde de Dijon", "Sel, poivre", "ail semoule", "Ciboulette"]'::jsonb,'["Préchauffer le four à 180°C.", "Faire cuire les pâtes dans une casserole d’eau bouillante salée, selon le temps indiqué sur le paquet. Les égoutter une fois cuites.", "Pendant la cuisson des pâtes, couper l’oignon rouge en fines lamelles. Couper les tomates cerises en deux, puis les placer dans un grand saladier. Réserver au frais.", "Dans un bol, mélanger le fromage blanc avec la moutarde classique et la moutarde à l’ancienne. Ajouter du sel, du poivre, de l’ail en poudre et de la ciboulette. Mélanger jusqu’à obtenir une sauce homogène. Réserver au frais.", "Étaler les pâtes égouttées sur une plaque de cuisson. Ajouter un filet d’huile d’olive à l’aide d’un pinceau ou d’un spray, puis enfourner pendant 10 minutes.", "Sortir la plaque du four, ajouter le parmesan râpé sur les pâtes, puis enfourner à nouveau pendant 10 minutes, jusqu’à ce qu’elles soient dorées et croustillantes.", "Ajouter les pâtes croustillantes dans le saladier avec l’oignon rouge et les tomates cerises. Émietter le thon par-dessus.", "Verser la sauce dans le saladier, puis mélanger délicatement pour bien répartir tous les ingrédients."]'::jsonb,'{}'::bigint[],'2026-05-26T17:36:02.924003+00:00');
insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (20,'837f7671-f72d-4150-87d6-d33020861082','Bagels au fromage frais, dinde et concombre','Plat','Facile',10,0,4,'Quand il fait trop chaud pour cuisiner, ces bagels sont la solution parfaite. Un repas simple, efficace et idéal pour l’été.','🍽️','https://joebqcuqqakymtlbvley.supabase.co/storage/v1/object/public/recipe-images/public/7b37ca28-1436-41e0-a072-b5b4df80d83f.webp',ARRAY['Salé','Healthy','Rapide','Déjeuner','Dîner','Quotidien','Sans cuisson']::text[],'["4 bagels", "200 g de fromage frais type St Môret", "4 tranches de blanc de dinde", "1/2 concombre", "Quelques feuilles de salade", "1 c. à soupe de ciboulette ciselée", "Poivre"]'::jsonb,'["Couper les bagels en deux.", "Mélanger le fromage frais avec la ciboulette et un peu de poivre.", "Tartiner généreusement chaque moitié de bagel.", "Ajouter les feuilles de salade.", "Répartir les tranches de dinde.", "Couper le concombre en fines rondelles et les disposer sur la dinde.", "Refermer les bagels et servir immédiatement."]'::jsonb,'{}'::bigint[],'2026-06-21T18:53:25.369772+00:00');
insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (24,'837f7671-f72d-4150-87d6-d33020861082','Citronade à la fraise','Boisson','Facile',9,0,4,'Une citronade à la fraise découverte avec Ugo : toute simple à faire, fraîche et un vrai régale. Parfaite pour l’été.','🍽️',null,ARRAY['Sucré','Rapide','Goûter','Invités','Sans cuisson']::text[],'["6 citrons", "200 g de fraises", "800 ml d’eau", "250 g de lait concentré sucré", "Glaçons"]'::jsonb,'["Enlevez la peau des citrons et mixez-les en entier.", "Ajoutez les fraises et l’eau, puis mixez le tout.", "Passez la préparation au tamis pour enlever les grains de fraises, la pulpe et le reste.", "Dans la préparation filtrée ajouté le lait concentré sucré, mélanger.", "Versez la préparation dans un verre avec des glaçon."]'::jsonb,'{}'::bigint[],'2026-07-18T10:18:02.74474+00:00');
insert into public.recipes (id,user_id,title,category,difficulty,prep_time,cook_time,servings,description,image,image_url,tags,ingredients,steps,related_recipe_ids,created_at) values (21,'837f7671-f72d-4150-87d6-d33020861082','Wrap façon salade César','Plat','Facile',15,0,4,'Quand la chaleur donne envie d’éviter les plaques et le four, ces wraps façon salade César sont une solution simple et efficace. Une recette fraîche, rapide à préparer et parfaite pour un repas d’été sans prise de tête.','🌯','https://joebqcuqqakymtlbvley.supabase.co/storage/v1/object/public/recipe-images/public/ac738ef9-528c-461c-a8d9-6b3dec4b606a.jpg',ARRAY['Salé','Healthy','Rapide','Déjeuner','Dîner','Quotidien','Sans cuisson']::text[],'["8 petites tortillas", "400 g de blanc de poulet rôti", "1 cœur de laitue romaine", "40 g de parmesan en copeaux", "1 poignée de croûtons", "150 g de fromage blanc", "1 c. à soupe de jus de citron", "1 c. à café de moutarde", "1 c. à soupe de parmesan râpé", "Sel", "Poivre"]'::jsonb,'["Laver et couper la laitue romaine en lanières.", "Préparer la sauce César légère : dans un bol, mélanger le fromage blanc, le jus de citron, la moutarde, le parmesan râpé, du sel et du poivre.", "Étaler un peu de sauce sur chaque tortilla.", "Ajouter la salade, le blanc de poulet rôti, les copeaux de parmesan et quelques croûtons légèrement concassés.", "Rabattre les côtés des tortillas, puis rouler les wraps bien serrés."]'::jsonb,'{}'::bigint[],'2026-06-21T19:01:36.413709+00:00');
