insert into public.site_ideas (id,user_id,title,message,category,status,created_at,updated_at) values (4,'837f7671-f72d-4150-87d6-d33020861082','quand on ajoute une recette','pouvoir faire des liens entre les recettes, par exemple dans la recette de quiche il y a de la pate brisé, faire un lien vers une recette pate brisé si elle existe, pouvoir créer le lien nous même','amelioration','nouvelle','2026-05-04T17:40:14.818897+00:00','2026-05-04T17:40:15.299+00:00');
insert into public.site_ideas (id,user_id,title,message,category,status,created_at,updated_at) values (5,'837f7671-f72d-4150-87d6-d33020861082','impression recette','Il faut retravailler ça, c''est pas très beau. La photo de la recette prend la moitié de la première page. Quand on veut imprimer la recette, ça met les avis, c''est inutile, imagine ton site devient connu on va avoir 15 pages pour la recette à cause des avis.','amelioration','nouvelle','2026-05-06T22:11:25.055688+00:00','2026-05-06T22:11:26.011+00:00');
insert into public.site_ideas (id,user_id,title,message,category,status,created_at,updated_at) values (6,'837f7671-f72d-4150-87d6-d33020861082','ajouter recette','Quand on ajoute une recette, ce serais bien de pouvoir interchangé les étapes de préparations, ou pouvoir ajouter une étape après une déjà fait j''explique je suis à la 14 étape et je me rend compte qu''il m''en manque une après la 3eme, quand j''appui ajouter une étape ce serais bien de pouvoir le faire en dessous de la 2eme. Je sais pas si tu me comprends.','amelioration','nouvelle','2026-05-10T10:30:01.667705+00:00','2026-05-10T10:30:01.777+00:00');
insert into public.user_follows (follower_id,following_id) values ('7036529a-9530-4a08-92f5-a89041d73f49','837f7671-f72d-4150-87d6-d33020861082');
insert into public.user_follows (follower_id,following_id) values ('837f7671-f72d-4150-87d6-d33020861082','7036529a-9530-4a08-92f5-a89041d73f49');
